
import type { OrderTaxJurisdictionRequest } from './OrderTaxJurisdictionRequest.js';

export type OrderTaxComponentRequest = ({ "calculation_type"?: "flat_amount" | (string & {}); /** Flat tax in the order currency. The amount must be at least 1 minor unit; otherwise, Flint returns INVALID_FLAT_TAX. */ "flat_money": ({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }); "jurisdiction": OrderTaxJurisdictionRequest; /** multipleOf: 0.0001. */ "percentage"?: number; "tax_type"?: "retail_delivery_fee" | (string & {}); });
